-- поток: fin; read-only; та же база rr_dt, что в расчёте 04.10.2026
select account,to_char((payload->>'rr_dt')::date,'YYYY-MM') ym,min((payload->>'rr_dt')::date)::text first_date,max((payload->>'rr_dt')::date)::text last_date,count(distinct (payload->>'rr_dt')::date) days,count(*) rows,sum(case payload->>'doc_type_name' when 'Продажа' then coalesce((payload->>'retail_amount')::numeric,0) when 'Возврат' then -coalesce((payload->>'retail_amount')::numeric,0) else 0 end) net,count(*) filter(where payload->>'doc_type_name'='Продажа' and (payload->>'retail_amount')::numeric>0) buys from raw_wb_report where (payload->>'rr_dt')::date between '2025-08-01' and '2025-09-30' or (payload->>'rr_dt')::date between '2026-08-01' and '2026-09-30' group by 1,2 order by 1,2;
